class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n
        ch = [{}]; cnt = [0]
        for w in words:
            cur = 0
            for c in w:
                nx = ch[cur].get(c)
                if nx is None:
                    ch.append({}); cnt.append(0)
                    nx = len(ch) - 1; ch[cur][c] = nx
                cur = nx; cnt[cur] += 1
        dep = [0] * len(cnt)
        from collections import deque
        dq = deque([0])
        while dq:
            u = dq.popleft()
            for c, v in ch[u].items():
                dep[v] = dep[u] + 1
                dq.append(v)
        mx = sorted(((dep[v], v) for v in range(1, len(cnt))
                     if cnt[v] >= k and not any(cnt[u] >= k for u in ch[v].values())),
                    reverse=True)[:3]
        res = []
        for wi, w in enumerate(words):
            cur = 0; best = 0; path = set()
            for c in w:
                cur = ch[cur][c]
                path.add(cur)
                if cnt[cur] >= k + 1:
                    best = max(best, dep[cur])
            for d, v in mx:
                if v not in path:
                    best = max(best, d)
            res.append(best)
        return res

