class Solution {
public:
    vector<int> longestCommonPrefix(vector<string>& words, int k) {
        int n = words.size();
        if (n - 1 < k) return vector<int>(n, 0);
        vector<array<int,26>> ch(1); ch[0].fill(-1);
        vector<int> cnt(1, 0), dep(1, 0);
        vector<int> leaf(n);
        for (int i = 0; i < n; i++) {
            int cur = 0;
            for (char c : words[i]) {
                int d = c - 'a';
                if (ch[cur][d] < 0) { ch.push_back({}); ch.back().fill(-1); cnt.push_back(0); dep.push_back(0); ch[cur][d] = ch.size()-1; }
                cur = ch[cur][d]; cnt[cur]++;
            }
            leaf[i] = cur;
        }
        vector<pair<int,int>> mx;
        for (int v = 1; v < (int)cnt.size(); v++) {
            bool anyQ = false;
            for (int d = 0; d < 26; d++) if (ch[v][d] >= 0 && cnt[ch[v][d]] >= k) anyQ = true;
            if (cnt[v] >= k && !anyQ) mx.push_back({dep[v], v});
        }
        sort(mx.rbegin(), mx.rend());
        if (mx.size() > 3) mx.resize(3);
        vector<int> res;
        for (int i = 0; i < n; i++) {
            int cur = 0, best = 0;
            unordered_set<int> path;
            for (char c : words[i]) {
                cur = ch[cur][c-'a']; path.insert(cur);
                if (cnt[cur] >= k + 1) best = max(best, dep[cur]);
            }
            for (auto& [d, v] : mx) if (!path.count(v)) best = max(best, d);
            res.push_back(best);
        }
        return res;
    }
};

