class Solution {
    public int[] longestCommonPrefix(String[] words, int k) {
        int n = words.length;
        if (n - 1 < k) return new int[n];
        List<Map<Character,Integer>> ch = new ArrayList<>();
        List<Integer> cnt = new ArrayList<>(), dep = new ArrayList<>();
        ch.add(new HashMap<>()); cnt.add(0); dep.add(0);
        int[] leaf = new int[n];
        for (int i = 0; i < n; i++) {
            int cur = 0;
            for (char c : words[i].toCharArray()) {
                Map<Character,Integer> m = ch.get(cur);
                Integer nx = m.get(c);
                if (nx == null) { nx = ch.size(); ch.add(new HashMap<>()); cnt.add(0); dep.add(0); m.put(c, nx); }
                cur = nx; cnt.set(cur, cnt.get(cur) + 1);
            }
            leaf[i] = cur;
        }
        ArrayDeque<Integer> dq = new ArrayDeque<>(List.of(0));
        while (!dq.isEmpty()) {
            int u = dq.poll();
            for (int v : ch.get(u).values()) { dep.set(v, dep.get(u) + 1); dq.add(v); }
        }
        List<int[]> mx = new ArrayList<>();
        for (int v = 1; v < cnt.size(); v++) {
            boolean anyQ = false;
            for (int u : ch.get(v).values()) if (cnt.get(u) >= k) anyQ = true;
            if (cnt.get(v) >= k && !anyQ) mx.add(new int[]{dep.get(v), v});
        }
        mx.sort((a, b) -> b[0] - a[0]);
        while (mx.size() > 3) mx.remove(mx.size() - 1);
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            int cur = 0, best = 0;
            Set<Integer> path = new HashSet<>();
            for (char c : words[i].toCharArray()) {
                cur = ch.get(cur).get(c); path.add(cur);
                if (cnt.get(cur) >= k + 1) best = Math.max(best, dep.get(cur));
            }
            for (int[] p : mx) if (!path.contains(p[1])) best = Math.max(best, p[0]);
            res[i] = best;
        }
        return res;
    }
}

