var longestCommonPrefix = function(words, k) {
    const n = words.length;
    if (n - 1 < k) return new Array(n).fill(0);
    const ch = [new Map()], cnt = [0], dep = [0];
    for (const w of words) {
        let cur = 0;
        for (const c of w) {
            let nx = ch[cur].get(c);
            if (nx === undefined) { nx = ch.length; ch.push(new Map()); cnt.push(0); dep.push(0); ch[cur].set(c, nx); }
            cur = nx; cnt[cur]++;
        }
    }
    const dq = [0];
    for (let h = 0; h < dq.length; h++) {
        for (const [c, v] of ch[dq[h]]) { dep[v] = dep[dq[h]] + 1; dq.push(v); }
    }
    const mx = [];
    for (let v = 1; v < cnt.length; v++) {
        let anyQ = false;
        for (const u of ch[v].values()) if (cnt[u] >= k) anyQ = true;
        if (cnt[v] >= k && !anyQ) mx.push([dep[v], v]);
    }
    mx.sort((a, b) => b[0] - a[0]);
    mx.length = Math.min(mx.length, 3);
    const res = [];
    for (const w of words) {
        let cur = 0, best = 0; const path = new Set();
        for (const c of w) {
            cur = ch[cur].get(c); path.add(cur);
            if (cnt[cur] >= k + 1) best = Math.max(best, dep[cur]);
        }
        for (const [d, v] of mx) if (!path.has(v)) best = Math.max(best, d);
        res.push(best);
    }
    return res;
};
